import { MeshBasicNodeMaterial } from 'three/webgpu';
import { PlaneGeometry, Group, Mesh, Color } from 'three';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: CGroup, Mesh: CMesh } = ctx.THREE;

  // Root container
  const root = new CGroup();

  // ---- Plane ----
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);
  material.transparent = true;

  const plane = new CMesh(geometry, material);
  // Apply position/rotation/scale from config (scenePlacement is handled by adapter,
  // but we still set local transforms if needed)
  plane.position.set(0, 0, 0);
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);
  root.add(plane);

  // Load texture asynchronously
  let texture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // Fail silently – keep material without texture
    });

  // ---- Text ----
  const textItems = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    const fontSize = item.typography?.fontSize ?? 39; // fallback to spec size
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above the plane
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // ---- User Data & Cleanup ----
  root.userData = {
    handlers: {},
    cleanup() {
      // Dispose material and geometry
      if (material) {
        material.dispose();
      }
      if (geometry) {
        geometry.dispose();
      }
      if (texture) {
        texture.dispose();
      }
      // Kill any GSAP timelines (none are created here, but safe guard)
      gsap.globalTimeline.clear();
      // Remove children
      root.traverse((obj) => {
        if (obj !== root && obj.parent) {
          obj.parent.remove(obj);
        }
      });
    },
  };

  return root;
}
